from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        equity = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy = equity.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(-500, 500, timedelta(days=0), timedelta(days=730))
        self.option_symbol = option.symbol

        self._five_minute_closes = deque(maxlen=21)
        self._entry_signal_bar_end = None

        self.held_option = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        self._five_minute_closes.append(float(bar.close))

        if len(self._five_minute_closes) < 21:
            return

        closes = list(self._five_minute_closes)
        previous_fast = sum(closes[15:20]) / 5.0
        previous_slow = sum(closes[0:20]) / 20.0
        current_fast = sum(closes[16:21]) / 5.0
        current_slow = sum(closes[1:21]) / 20.0

        end_time = bar.end_time
        eligible_time = (
            (end_time.hour, end_time.minute) >= (9, 45)
            and (end_time.hour, end_time.minute) <= (14, 30)
        )

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self._entry_signal_bar_end = end_time

    def on_data(self, slice):
        self._handle_unexpected_spy_position()

        if self.held_option is not None and not self._has_option_position():
            if self.exit_order_id is None or not self._is_order_open(self.exit_order_id):
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None

        if self.held_option is not None and self.time.date() >= self.held_expiry.date():
            self.no_entry_date = self.time.date()
            self._submit_option_exit("expiration safety")

        if self.held_option is not None:
            if (
                self.time.date() == self._previous_trading_day(self.held_expiry.date())
                and self.time.hour == 15
                and self.time.minute == 45
            ):
                self._submit_option_exit("15:45 pre-expiration time stop")
            else:
                self._check_profit_target(slice)

        if self._entry_signal_bar_end == self.time:
            self._entry_signal_bar_end = None
            self._process_entry_signal(slice)

    def _process_entry_signal(self, slice):
        if self.no_entry_date == self.time.date():
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: entry skipped; no SPY option chain")
            return

        spy_price = float(self.securities[self.spy].price)
        if spy_price <= 0:
            self.debug(f"{self.time}: entry skipped; invalid SPY price")
            return

        minimum_expiry_date = self.time.date() + timedelta(days=7)
        expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.expiry.date() >= minimum_expiry_date
        })

        if not expiries:
            self.debug(f"{self.time}: entry skipped; no eligible expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug(f"{self.time}: entry skipped; no eligible call")
            return

        selected = min(candidates, key=lambda c: (float(c.strike), str(c.symbol)))
        ticket = self.market_order(selected.symbol, 1)

        if ticket is None:
            self.debug(f"{self.time}: entry skipped; market order was not created")
            return

        self.entry_order_id = ticket.order_id
        self.held_expiry = selected.expiry
        self.debug(
            f"{self.time}: entry submitted {selected.symbol} "
            f"expiry {selected.expiry.date()} strike {selected.strike}"
        )

    def _check_profit_target(self, slice):
        if self.entry_price is None or self.entry_price <= 0:
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.symbol == self.held_option),
            None
        )
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason):
        if self.held_option is None or not self._has_option_position():
            return

        if self.exit_order_id is not None and self._is_order_open(self.exit_order_id):
            return

        for order in self.transactions.get_open_orders(self.held_option):
            if order.quantity < 0:
                self.transactions.cancel_order(order.id)

        quantity = int(self.securities[self.held_option].holdings.quantity)
        if quantity == 0:
            return

        ticket = self.market_order(self.held_option, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.order_id
            self.debug(f"{self.time}: exit submitted {self.held_option}; {reason}")

    def _handle_unexpected_spy_position(self):
        quantity = int(self.securities[self.spy].holdings.quantity)
        if quantity == 0:
            self.spy_liquidation_order_id = None
            return

        if (
            self.spy_liquidation_order_id is not None
            and self._is_order_open(self.spy_liquidation_order_id)
        ):
            return

        ticket = self.market_order(self.spy, -quantity)
        if ticket is not None:
            self.spy_liquidation_order_id = ticket.order_id
            self.debug(f"{self.time}: unexpected SPY exercise/assignment; liquidating {quantity}")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _has_option_position(self):
        return (
            self.held_option is not None
            and self.held_option in self.securities
            and self.securities[self.held_option].holdings.quantity != 0
        )

    def _is_order_open(self, order_id):
        order = self.transactions.get_order_by_id(order_id)
        return order is not None and order.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )

    def on_order_event(self, order_event):
        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED and order_event.fill_quantity > 0:
                self.held_option = order_event.symbol
                self.entry_price = float(order_event.fill_price)
                self.entry_order_id = None
                self.debug(
                    f"{self.time}: entry filled {self.held_option} "
                    f"at {self.entry_price:.4f}"
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_id = None
                self.held_expiry = None
                self.debug(f"{self.time}: entry order did not complete")

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"{self.time}: exit filled {order_event.symbol}")
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None

        if (
            order_event.order_id == self.spy_liquidation_order_id
            and order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID)
        ):
            self.spy_liquidation_order_id = None

