from AlgorithmImports import *


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self._spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self._spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self._option = self.AddOption("SPY", Resolution.Minute)
        self._option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))
        self._option_symbol = self._option.Symbol

        self._five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute.DataConsolidated += self._on_five_minute_bar

        self._closes = RollingWindow[float](21)
        self._previous_fast = None
        self._previous_slow = None
        self._current_slice = None

        self._entry_pending = False
        self._entry_order_id = None
        self._exit_order_id = None
        self._held_option = None
        self._entry_price = None
        self._no_entry_today = None
        self._spy_liquidation_pending = False

    def OnData(self, data: Slice):
        self._current_slice = data

        self._handle_unexpected_spy_position()

        if self._held_option is not None:
            if not self.Portfolio[self._held_option].Invested:
                self._clear_option_state()
            else:
                expiration = self._held_option.ID.Date.date()
                if self.Time.date() >= expiration:
                    self._no_entry_today = self.Time.date()
                    self._submit_option_exit(
                        "Expiration safeguard",
                        "Expiration processing began; liquidating held option"
                    )
                else:
                    self._evaluate_option_exits(data)

        if data.Bars.ContainsKey(self._spy):
            self._five_minute.Update(data.Bars[self._spy])

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        self._closes.Add(float(bar.Close))

        if self._closes.Count < 20:
            return

        fast = sum(self._closes[i] for i in range(5)) / 5.0
        slow = sum(self._closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self._previous_fast is not None and
            self._previous_slow is not None and
            self._previous_fast <= self._previous_slow and
            fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        bar_time = bar.EndTime
        eligible_time = (
            (bar_time.hour == 9 and bar_time.minute >= 45) or
            (10 <= bar_time.hour <= 13) or
            (bar_time.hour == 14 and bar_time.minute <= 30)
        )

        if not bullish_cross or not eligible_time:
            return

        if self._no_entry_today == self.Time.date():
            return

        if self._entry_pending or self._held_option is not None:
            return

        if self._current_slice is None:
            return

        self._enter_call(self._current_slice, float(bar.Close))

    def _enter_call(self, data: Slice, spy_price: float):
        if not data.OptionChains.ContainsKey(self._option_symbol):
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice")
            return

        chain = data.OptionChains[self._option_symbol]
        minimum_expiration = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying expiration")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying call at {expiration}")
            return

        contract = min(candidates, key=lambda x: (float(x.Strike), str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        self._entry_pending = True
        self._entry_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Entering 1 {contract.Symbol}")

    def _evaluate_option_exits(self, data: Slice):
        if self._held_option is None or self._entry_price is None:
            return

        expiration = self._held_option.ID.Date.date()
        if self.Time.hour == 15 and self.Time.minute == 45:
            if self.Time.date() == self._previous_trading_day(expiration):
                self._submit_option_exit(
                    "Pre-expiration time stop",
                    f"15:45 time stop for {self._held_option}"
                )
                return

        if not data.QuoteBars.ContainsKey(self._held_option):
            return

        quote = data.QuoteBars[self._held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_option_exit(
                "Profit target",
                f"50% profit target reached for {self._held_option}"
            )

    def _submit_option_exit(self, reason: str, message: str):
        if self._held_option is None or self._exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self._held_option):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity == 0:
            self._clear_option_state()
            return

        ticket = self.MarketOrder(self._held_option, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: {reason}: {message}")

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self._spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, datetime.min.time())
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity

        if quantity == 0:
            self._spy_liquidation_pending = False
            return

        if not self._spy_liquidation_pending:
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position "
                f"({quantity}); liquidating"
            )
            self.MarketOrder(self._spy, -quantity)
            self._spy_liquidation_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self._held_option = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_pending = False
                self._entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled {self._held_option} "
                    f"at {self._entry_price}"
                )
