from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionFilterUniverse = None
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-200, 200)
                                     .Expiration(timedelta(0), timedelta(days=730))
        )

        self.closes = []
        self.pending_entry_signal = False
        self.signal_bar_end = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.time_stop_submitted = False
        self.block_entries_on = None
        self.stock_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0

        self.closes.append(float(bar.Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if previous_fast is None or len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0
        bar_end = bar.EndTime

        if (previous_fast <= previous_slow and current_fast > current_slow
                and time(9, 45) <= bar_end.time() <= time(14, 30)):
            self.pending_entry_signal = True
            self.signal_bar_end = bar_end

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity == 0 and self.entry_order_id is None:
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
                self.time_stop_submitted = False
            else:
                self.HandleExpirationProtection()
                self.HandleOptionExit(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.block_entries_on == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        try:
            spy_price = float(data.Bars[self.spy].Close)
        except Exception:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        contracts = []
        try:
            for chain in data.OptionChains.Values:
                for contract in chain:
                    contracts.append(contract)
        except Exception:
            self.Debug("Skipped entry: no option chain.")
            return

        if not contracts:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no eligible call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_symbol = selected.Symbol
        self.held_expiry = selected.Expiry
        self.entry_price = None
        self.exit_order_id = None
        self.time_stop_submitted = False
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected.Expiry.date()} "
            f"strike {selected.Strike}"
        )

    def HandleOptionExit(self, data):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if (self.held_expiry is not None
                and self.Time.date() >= self.held_expiry.date()):
            self.block_entries_on = self.Time.date()
            self.SubmitExit("expiration protection")
            return

        if (self.held_expiry is not None
                and self.Time.time() == time(15, 45)
                and self.IsTradingDayImmediatelyBeforeExpiry()):
            self.time_stop_submitted = True
            self.SubmitExit("15:45 pre-expiration time stop")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        quote = self.GetHeldContractQuote(data)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def GetHeldContractQuote(self, data):
        if self.held_symbol is None:
            return None

        try:
            for chain in data.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == self.held_symbol:
                        bid = float(contract.BidPrice)
                        ask = float(contract.AskPrice)
                        if bid > 0 and ask > 0:
                            return bid, ask
                        return None
        except Exception:
            return None

        return None

    def IsTradingDayImmediatelyBeforeExpiry(self):
        if self.held_expiry is None:
            return False

        candidate = self.Time.date() + timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate += timedelta(days=1)

        return candidate == self.held_expiry.date()

    def HandleExpirationProtection(self):
        if self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.block_entries_on = self.Time.date()
            if self.exit_order_id is None:
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_symbol}")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.stock_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.stock_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position; liquidation submitted.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity == 0:
                    self.held_symbol = None
                    self.held_expiry = None
                self.Debug(f"Entry failed: {order_event.Symbol}")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
                self.exit_order_id = None
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.time_stop_submitted = False
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.stock_liquidation_order_id:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.stock_liquidation_order_id = None

