        self.bucket_close = minute_bar.Close

        if minutes_after_open % 5 == 0:
            self.FinalizeFiveMinuteBar(data, bar_end)
            self.bucket_date = None
            self.bucket_index = None
            self.bucket_minutes = set()
            self.bucket_close = None

    def FinalizeFiveMinuteBar(self, data, current_time):
        if self.bucket_close is None or len(self.bucket_minutes) != 5:
            return

        self.fast_closes.append(self.bucket_close)
        self.slow_closes.append(self.bucket_close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

