        if (
            self.held_contract is None
            or not self.Portfolio[self.held_contract].Invested
            or self.IsOrderOpen(self.exit_ticket)
        ):
            return

        expiry = self.held_contract.ID.Date.date()
        today = self.Time.date()

        if today < expiry and self.IsLastTradingDayBeforeExpiry(today, expiry):
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationProtection(self):
        if (
            self.held_contract is None
            or not self.Portfolio[self.held_contract].Invested
        ):
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_reentry_date = self.Time.date()
            if not self.IsOrderOpen(self.exit_ticket):
                self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.spy_liquidation_ticket is None or not self.IsOrderOpen(self.spy_liquidation_ticket):
            quantity = self.Portfolio[self.spy].Quantity
            self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def GetCurrentQuote(self, data, symbol):
        chain = data.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        quote_bar = data.QuoteBars.get(symbol)
        if quote_bar is not None and quote_bar.Bid is not None and quote_bar.Ask is not None:
            return float(quote_bar.Bid.Close), float(quote_bar.Ask.Close)

        return 0.0, 0.0

    def IsLastTradingDayBeforeExpiry(self, today, expiry):
        day = today + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while day < expiry:
            if exchange_hours.IsDateOpen(datetime.combine(day, dt_time.min)):
                return False
            day += timedelta(days=1)

        return True

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
                self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity < 0:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.entry_fill_price = None
                    self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

