        self.time_stop_sent = False
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        end_time = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= end_time <= time(14, 30):
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleHeldOptionExit(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None:
            return

        if self._OrderIsOpen(self.entry_ticket) or self._OrderIsOpen(self.exit_ticket):
            return

        if self.Portfolio[self.spy].Quantity != 0 or self._OrderIsOpen(self.spy_liquidation_ticket):
            return

        if not data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain in Slice")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price")
            return

        eligible = []
        minimum_expiry = self.Time.date() + timedelta(days=7)

        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                eligible.append(contract)

        if not eligible:
            self.Debug("Entry skipped: no eligible call expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def HandleHeldOptionExit(self, data):
        if self.held_contract is None:
            return

        if self._OrderIsOpen(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_contract]
        if holding.Quantity <= 0:
            self._ClearOptionState()
            return

        if self.entry_price is not None:
            midpoint = self.GetCurrentMidpoint(data, self.held_contract)
            if midpoint is not None and midpoint >= self.entry_price * 1.50:
                self.exit_ticket = self.MarketOrder(self.held_contract, -holding.Quantity)
                self.Debug("Profit-target exit submitted: {0}".format(self.held_contract))
                return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() == self.PreviousTradingDay(expiry) and self.Time.time() == time(15, 45):
            self.time_stop_sent = True
            self.exit_ticket = self.MarketOrder(self.held_contract, -holding.Quantity)
            self.Debug("Time-stop exit submitted: {0}".format(self.held_contract))

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() < expiry:
            return

        self.blocked_entry_date = self.Time.date()

        if self._OrderIsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity > 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.Debug("Expiration-protection exit submitted: {0}".format(self.held_contract))

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self._OrderIsOpen(self.spy_liquidation_ticket):
            return

        self.Debug("Unexpected SPY exercise/assignment position; liquidating")
        self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def GetCurrentMidpoint(self, data, symbol):
        for chain in data.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is None:
                continue

            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while True:
            market_date = datetime.combine(candidate, time.min)
            if exchange_hours.IsDateOpen(market_date):
                return candidate
            candidate -= timedelta(days=1)

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_liquidation_ticket = None
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled] and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.time_stop_sent = False
                self.Debug(
                    "Entry filled: {0} @ {1:.2f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
            return

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
                self.Debug(
                    "Exit fill: {0} @ {1:.2f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                if self.held_contract is None or self.Portfolio[self.held_contract].Quantity <= 0:
                    self._ClearOptionState()

    def _ClearOptionState(self):
        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.time_stop_sent = False

    def _OrderIsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

