from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=90)
            )
        )
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_last_time = None
        self.bucket_count = 0
        self.bucket_valid = False
        self.bucket_close = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.pending_entry_symbol = None
        self.time_stop_date = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar, data)

        self._manage_open_option(data)

    def _update_five_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minutes_since_midnight = end_time.hour * 60 + end_time.minute
        bucket_minutes = ((minutes_since_midnight + 4) // 5) * 5
        bucket_end = end_time.replace(
            hour=0, minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minutes)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_last_time = None
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_close = None

        if self.bucket_last_time is not None:
            if end_time != self.bucket_last_time + timedelta(minutes=1):
                self.bucket_valid = False

        self.bucket_last_time = end_time
        self.bucket_count += 1
        self.bucket_close = bar.Close

        if end_time != self.bucket_end:
            return

        if self.bucket_valid and self.bucket_count == 5:
            self._on_completed_five_minute_bar(end_time, self.bucket_close, data)

        self.bucket_end = None
        self.bucket_last_time = None
        self.bucket_count = 0
        self.bucket_valid = False
        self.bucket_close = None

    def _on_completed_five_minute_bar(self, end_time, close, data: Slice):
        self.closes.Add(float(close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if end_time.time() < time(9, 45) or end_time.time() > time(14, 30):
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self._has_option_position() or self._has_open_entry_order():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [contract for contract in chain if contract.Right == OptionRight.Call]

        eligible_expiries = sorted(
            {contract.Expiry.date() for contract in calls if contract.Expiry.date() >= minimum_expiry}
        )
        if not eligible_expiries:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract
            for contract in calls
            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def _manage_open_option(self, data: Slice):
        if not self._has_option_position():
            return

        if self._has_open_exit_order():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if self.entry_price is not None and midpoint >= self.entry_price * 1.50:
                    self._submit_exit("profit target")
                    return

        if (
            self.time_stop_date == self.Time.date()
            and self.Time.time() == time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if not self._has_option_position() or self._has_open_exit_order():
            return

