        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(0, 180)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_time = None

        self.held_contract = None
        self.entry_order_id = None
        self.entry_contract = None
        self.entry_price = None
        self.exit_order_id = None
        self.spy_flatten_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            current_fast = self.fast.Current.Value
            current_slow = self.slow.Current.Value

            if (self.previous_fast is not None and
                    self.previous_fast <= self.previous_slow and
                    current_fast > current_slow and
                    self.IsEntryTime(bar.EndTime)):
                self.pending_signal_time = bar.EndTime

            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is not None and self.Time.date() >= self.held_contract.ID.Date.date():
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity != 0:
                self.Debug("Expiration safeguard: liquidating {0}".format(self.held_contract))
                self.SubmitExit("expiration safeguard")

        self.EvaluateExit(slice)

        if self.pending_signal_time is not None:
            if self.pending_signal_time == self.Time:
                self.pending_signal_time = None
                self.TryEnter(slice)
            elif self.pending_signal_time < self.Time:
                self.pending_signal_time = None

    def TryEnter(self, slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.HasOptionPosition() or self.EntryOrderOpen() or self.ExitOrderOpen():
            return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: no current SPY bar.")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        underlying_price = slice.Bars[self.spy].Close
        minimum_strike = underlying_price * Decimal("1.01")
        minimum_expiry = self.Time.date() + timedelta(days=7)
        chain = slice.OptionChains[self.option_symbol]

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_contract = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def EvaluateExit(self, slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            if not self.ExitOrderOpen():
                self.ResetOptionState()
            return

        expiry_date = self.held_contract.ID.Date.date()
        if (self.Time.date() == self.PreviousTradingDate(expiry_date) and
                self.Time.hour == 15 and self.Time.minute == 45):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None or not slice.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / Decimal("2")
        if midpoint >= self.entry_price * Decimal("1.50"):
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None or self.ExitOrderOpen():
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.entry_order_id is None or order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self.ResetOptionState()
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({0}): {1}".format(reason, self.held_contract))

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if self.spy_flatten_order_id is None:
            ticket = self.Liquidate(self.spy)
            self.spy_flatten_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position: liquidating SPY.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = self.entry_contract
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.entry_contract = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_contract, self.entry_price
                    )
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order did not fill: {0}".format(order_event.Status))
                self.entry_order_id = None
                self.entry_contract = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                if self.held_contract is None or self.Portfolio[self.held_contract].Quantity == 0:
                    self.ResetOptionState()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.spy_flatten_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_flatten_order_id = None

        self.HandleUnexpectedSpyPosition()

    def HasOptionPosition(self):
        return (
            self.held_contract is not None and
            self.Portfolio[self.held_contract].Quantity != 0
        )

    def EntryOrderOpen(self):
        if self.entry_order_id is None:
            return False
        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ]

    def ExitOrderOpen(self):
        if self.exit_order_id is None:
            return False
        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ]

    def ResetOptionState(self):
        self.held_contract = None
        self.entry_price = None
        self.exit_order_id = None

    def PreviousTradingDate(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def IsEntryTime(self, time):
        if time.hour == 9:
            return time.minute >= 45
        if 10 <= time.hour <= 13:
            return True
        return time.hour == 14 and time.minute <= 30

